sys_script.script:
(function executeRule(current, previous) {

    // =========================================================
    // 1. AUTO-CATEGORIZE COMPLAINT
    // =========================================================

    if (current.complaint_category.nil()) {

        var desc = (current.getValue('description') || '').toLowerCase();

        // Plumbing
        if (desc.indexOf('leak') > -1 ||
            desc.indexOf('pipe') > -1 ||
            desc.indexOf('drain') > -1) {

            current.setValue('complaint_category', 'Plumbing');

            // Water Supply
        } else if (desc.indexOf('tap') > -1 ||
            desc.indexOf('water supply') > -1 ||
            desc.indexOf('no water') > -1) {

            current.setValue('complaint_category', 'Water Supply');

            // HVAC
        } else if (desc.indexOf('hvac') > -1 ||
            desc.indexOf('air conditioner') > -1 ||
            desc.indexOf('air conditioning') > -1 ||
            desc.indexOf(' ac ') > -1 ||
            desc.indexOf('cooling') > -1 ||
            desc.indexOf('heating') > -1) {

            current.setValue('complaint_category', 'HVAC');

            // Security
        } else if (desc.indexOf('cctv') > -1 ||
            desc.indexOf('camera') > -1 ||
            desc.indexOf('gate') > -1 ||
            desc.indexOf('guard') > -1 ||
            desc.indexOf('security') > -1) {

            current.setValue('complaint_category', 'Security');

            // Generator
        } else if (desc.indexOf('generator') > -1) {

            current.setValue('complaint_category', 'Generator');

            // Elevator
        } else if (desc.indexOf('lift') > -1 ||
            desc.indexOf('elevator') > -1) {

            current.setValue('complaint_category', 'Elevator');

            // Electrical
        } else if (desc.indexOf('electrical') > -1 ||
            desc.indexOf('switch') > -1 ||
            desc.indexOf('wiring') > -1 ||
            desc.indexOf('socket') > -1 ||
            desc.indexOf('bulb') > -1 ||
            desc.indexOf('light') > -1 ||
            desc.indexOf('power failure') > -1) {

            current.setValue('complaint_category', 'Electrical');

            // Civil
        } else if (desc.indexOf('wall') > -1 ||
            desc.indexOf('floor') > -1 ||
            desc.indexOf('ceiling') > -1 ||
            desc.indexOf('crack') > -1 ||
            desc.indexOf('building') > -1 ||
            desc.indexOf('civil') > -1) {

            current.setValue('complaint_category', 'Civil');

            // Other
        } else {

            current.setValue('complaint_category', 'Other');
        }
    }


    // =========================================================
    // 2. CALCULATE BASE PRIORITY FROM RESIDENT SEVERITY
    // =========================================================

    var severity = (current.getDisplayValue('resident_severity') || '')
        .toLowerCase();

    var basePriority = 4;

    if (severity == 'critical') {

        basePriority = 1;

    } else if (severity == 'high') {

        basePriority = 2;

    } else if (severity == 'medium') {

        basePriority = 3;

    } else if (severity == 'low') {

        basePriority = 4;
    }


    // =========================================================
    // 3. INCREASE PRIORITY FOR REPEATED CI FAILURES
    // =========================================================

    if (!current.cmdb_ci.nil()) {

        var asset = current.cmdb_ci.getRefRecord();

        if (asset.isValidRecord()) {

            var faultCount = parseInt(
                asset.getValue('fault_count') || '0',
                10
            );

            // Increase fault count
            faultCount++;

            // Save updated fault count on the CI
            asset.setValue('fault_count', faultCount);
            asset.update();

            // If the CI has repeated failures,
            // increase priority by one level.
            if (faultCount >= 3 && basePriority > 1) {

                basePriority--;
            }
        }
    }


    // =========================================================
    // 4. SET FINAL PRIORITY
    // =========================================================

    current.setValue('priority', basePriority.toString());


})(current, previous);
